import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

// 가정: 계정과목별 금액은 전표 분개의 (차변 - 대변) 합계와 결산자료 금액의 합이다.
// 가정: 승인해제 전표와 마감취소 결산자료는 집계에서 제외한다.
// 가정: 회계단위는 결산자료에만 있으므로 결산자료에만 조건으로 건다.
// 가정: 재무제표 양식(financial_statement_form)에 등록된 종류는 사용 중인 양식 계정만 보이고, 양식이 없는 종류는 집계된 모든 계정과목을 보인다.
const VOUCHER_SUB =
  '(SELECT vl.account_item_id AS account_item_id, ' +
  "SUM(CASE WHEN vl.dc_type = 'DEBIT' THEN vl.amount ELSE -vl.amount END) AS amt " +
  'FROM voucher_line vl ' +
  'JOIN journal_voucher jv ON jv.journal_voucher_id = vl.journal_voucher_id ' +
  "WHERE jv.status IN ('승인', '마감') " +
  'AND jv.voucher_date >= CAST(:periodStart AS date) ' +
  'AND jv.voucher_date <= CAST(:periodEnd AS date) ' +
  'GROUP BY vl.account_item_id)';

const CLOSING_SUB =
  '(SELECT ce.account_item_id AS account_item_id, SUM(ce.closing_amount) AS amt ' +
  'FROM closing_entry ce ' +
  "WHERE ce.status <> '마감취소' " +
  'AND ce.period_start >= CAST(:periodStart AS date) ' +
  'AND ce.period_end <= CAST(:periodEnd AS date) ' +
  'AND (CAST(:unit AS varchar) IS NULL OR ce.accounting_unit = CAST(:unit AS varchar)) ' +
  'GROUP BY ce.account_item_id)';

const FROM_SQL =
  'FROM account_item a ' +
  'LEFT JOIN ' + VOUCHER_SUB + ' v ON v.account_item_id = a.account_item_id ' +
  'LEFT JOIN ' + CLOSING_SUB + ' c ON c.account_item_id = a.account_item_id ' +
  'WHERE (v.account_item_id IS NOT NULL OR c.account_item_id IS NOT NULL) ' +
  'AND (' +
  'NOT EXISTS (SELECT 1 FROM financial_statement_form f0 WHERE f0.statement_type = :statementType) ' +
  'OR EXISTS (SELECT 1 FROM financial_statement_form f1 ' +
  'WHERE f1.statement_type = :statementType ' +
  'AND f1.account_item_id = a.account_item_id ' +
  "AND f1.use_yn = '사용')" +
  ')';

function text(value: unknown): string {
  if (value === undefined || value === null) {
    return '';
  }
  return String(value).trim();
}

@Controller('api/v1')
export class FnSfr01002Controller {
  @Get('/financial-statements')
  async listFinancialStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const query = checks.queryOf(req.query);

    const statementType = text(query['statementType']);
    const periodStart = text(query['periodStart']);
    const periodEnd = text(query['periodEnd']);
    const accountingUnit = text(query['accountingUnit']);

    if (statementType === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '재무제표 종류를 선택해 주세요.');
    }
    if (accountingUnit.length > 50) {
      throw new ApiError(400, 'VALIDATION_FAILED', '회계단위는 50자 이하로 입력해 주세요.');
    }
    if (periodStart === '' || periodEnd === '') {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 기간(시작일·종료일)을 모두 입력해 주세요.');
    }
    if (!DATE_PATTERN.test(periodStart) || !DATE_PATTERN.test(periodEnd)) {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 기간은 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (periodStart > periodEnd) {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 시작일이 종료일보다 늦을 수 없습니다.');
    }

    const pageText = text(query['page']);
    const sizeText = text(query['size']);
    const page = pageText === '' ? 0 : Number(pageText);
    const size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);

    return transaction(async (db) => {
      const baseParams = {
        statementType,
        periodStart,
        periodEnd,
        unit: accountingUnit === '' ? null : accountingUnit,
      };
      const rows = await db.query(
        'SELECT a.account_item_id AS "accountItemId", ' +
          'a.account_code AS "accountCode", ' +
          'a.account_name AS "accountName", ' +
          '(COALESCE(v.amt, 0) + COALESCE(c.amt, 0)) AS "amount" ' +
          FROM_SQL +
          ' ORDER BY a.account_code LIMIT :limit OFFSET :offset',
        { ...baseParams, limit, offset: page * limit },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" ' + FROM_SQL,
        baseParams,
      );
      const total = counts.length > 0 ? Number(counts[0]['total']) : 0;
      return { items: rows, page, size: limit, total };
    });
  }
}

