import { useState } from 'react';
import { call, useData, Filters, Band, DataTable, Pager, Field, Select, DateInput, TextInput, Tiles, Num, ErrorText } from '../kit';
import type { PageProps, Page, Row } from '../kit';

const STATEMENT_TYPES: [string, string][] = [
  ['합계잔액시산표', '합계잔액시산표'],
  ['잔액시산표', '잔액시산표'],
  ['일·월계표', '일·월계표'],
  ['재무상태표', '재무상태표'],
  ['손익계산서', '손익계산서'],
  ['원가보고서', '원가보고서'],
  ['이익잉여금처분계산서', '이익잉여금처분계산서'],
  ['자본변동표', '자본변동표'],
  ['현금흐름표', '현금흐름표'],
  ['결산부속명세서', '결산부속명세서'],
  ['기간비용 현황', '기간비용 현황'],
];

const PAGE_SIZE = 20;

interface Applied {
  statementType: string;
  periodStart: string;
  periodEnd: string;
  accountingUnit: string;
}

export default function FnSfr01002Page({ role, notify }: PageProps) {
  const [statementType, setStatementType] = useState('');
  const [periodStart, setPeriodStart] = useState('');
  const [periodEnd, setPeriodEnd] = useState('');
  const [accountingUnit, setAccountingUnit] = useState('');
  const [applied, setApplied] = useState<Applied | null>(null);
  const [page, setPage] = useState(0);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(async () => {
    if (applied === null) {
      return { items: [], page: 0, size: PAGE_SIZE, total: 0 };
    }
    return call<Page>('GET', '/financial-statements', role, undefined, {
      statementType: applied.statementType,
      periodStart: applied.periodStart,
      periodEnd: applied.periodEnd,
      accountingUnit: applied.accountingUnit,
      page,
      size: PAGE_SIZE,
    });
  }, [applied, page, role]);

  const search = () => {
    if (statementType === '') {
      setFormError('재무제표 종류를 선택해 주세요.');
      return;
    }
    if (periodStart === '' || periodEnd === '') {
      setFormError('조회 기간(시작일·종료일)을 모두 입력해 주세요.');
      return;
    }
    if (periodStart > periodEnd) {
      setFormError('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ statementType, periodStart, periodEnd, accountingUnit });
  };

  const reset = () => {
    setStatementType('');
    setPeriodStart('');
    setPeriodEnd('');
    setAccountingUnit('');
    setFormError('');
    setPage(0);
    setApplied(null);
  };

  const items: Row[] = data ? data.items : [];
  const total = data ? data.total : 0;
  const pageSum = items.reduce((sum, row) => sum + Number(row['amount'] ?? 0), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles
          items={[
            ['재무제표', applied ? applied.statementType : '-'],
            ['계정과목 수', <Num value={total} />],
            ['현재 쪽 금액 합계', <Num value={pageSum} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>재무제표 조회</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="재무제표 종류" required>
            <Select value={statementType} onChange={setStatementType} options={STATEMENT_TYPES} />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={periodStart} onChange={setPeriodStart} />
          </Field>
          <Field label="조회 종료일 또는 기준일" required>
            <DateInput value={periodEnd} onChange={setPeriodEnd} />
          </Field>
          <Field label="회계단위">
            <TextInput value={accountingUnit} onChange={setAccountingUnit} />
          </Field>
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={total} />
        <DataTable
          columns={[
            { key: 'accountCode', label: '계정과목 코드' },
            { key: 'accountName', label: '계정과목 명칭' },
            { key: 'amount', label: '계정과목별 집계 금액', render: (row: Row) => <Num value={row['amount']} /> },
          ]}
          rows={items}
          empty={loading ? '불러오는 중입니다.' : applied ? '조회된 데이터가 없습니다.' : '조건을 선택하고 조회해 주세요.'}
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>
    </div>
  );
}
